insert into foods (name, group_code, portion, portion_g, kcal, protein_g, fat_g, carbs_g, fiber_g, is_base)
select f.name, f.grp, f.portion, f.g, g.kcal, g.protein_g, g.fat_g, g.carbs_g, f.fiber, true
from _foods f join equivalent_groups g on g.code = f.grp;

-- ============ Recetas ============
insert into recipes (name, description, meal_time, tags, servings, prep_minutes, ingredients, steps, equivalents, is_base) values
('Avena cocida con manzana y canela', 'Desayuno alto en fibra soluble.', 'desayuno', '{normal,diabetes,dislipidemia}', 1, 10,
 '[{"name":"Avena en hojuelas","quantity":"2/3","unit":"taza"},{"name":"Leche descremada","quantity":"1","unit":"taza"},{"name":"Manzana picada","quantity":"1","unit":"pieza"},{"name":"Canela","quantity":"al gusto","unit":""},{"name":"Nuez","quantity":"3","unit":"piezas"}]',
 '{"Calienta la leche a fuego medio.","Agrega la avena y cocina 5 minutos moviendo.","Añade la manzana picada y la canela.","Sirve y decora con la nuez troceada."}',
 '{"cereales_sg":2,"leche_d":1,"frutas":1,"grasas_cp":1}', true),
('Omelette de claras con espinaca y champiñón', 'Alto en proteína, bajo en grasa.', 'desayuno', '{normal,diabetes,hipertension,alta_proteina,dislipidemia}', 1, 12,
 '[{"name":"Claras de huevo","quantity":"4","unit":"piezas"},{"name":"Espinaca","quantity":"1","unit":"taza"},{"name":"Champiñón","quantity":"1/2","unit":"taza"},{"name":"Aceite de oliva","quantity":"1","unit":"cucharadita"},{"name":"Tortilla de maíz","quantity":"2","unit":"piezas"}]',
 '{"Saltea champiñón y espinaca en el aceite 3 minutos.","Bate las claras con pimienta y hierbas (sin sal añadida).","Vierte sobre las verduras y cocina tapado a fuego bajo.","Dobla y acompaña con las tortillas calientes."}',
 '{"aoa_mb":2,"verduras":1,"grasas_sp":1,"cereales_sg":2}', true),
('Chilaquiles horneados de pollo', 'Versión ligera con totopo horneado.', 'desayuno', '{normal}', 1, 20,
 '[{"name":"Tortilla de maíz","quantity":"2","unit":"piezas"},{"name":"Salsa verde casera","quantity":"1/2","unit":"taza"},{"name":"Pechuga de pollo deshebrada","quantity":"60","unit":"g"},{"name":"Queso fresco","quantity":"40","unit":"g"},{"name":"Crema","quantity":"1","unit":"cucharada"}]',
 '{"Corta las tortillas en triángulos y hornea a 180 °C 10 minutos.","Calienta la salsa y agrega los totopos.","Sirve con pollo, queso y crema."}',
 '{"cereales_sg":2,"verduras":1,"aoa_mb":2,"aoa_b":1,"grasas_sp":1}', true),
('Yogur griego con frutos rojos y chía', 'Colación rica en proteína.', 'colacion', '{normal,diabetes,embarazo,alta_proteina}', 1, 5,
 '[{"name":"Yogur griego natural sin grasa","quantity":"3/4","unit":"taza"},{"name":"Fresas","quantity":"1/2","unit":"taza"},{"name":"Arándanos","quantity":"1/3","unit":"taza"},{"name":"Chía","quantity":"2","unit":"cucharadas"}]',
 '{"Sirve el yogur en un tazón.","Agrega la fruta lavada y desinfectada.","Espolvorea la chía."}',
 '{"leche_d":1,"frutas":1,"grasas_cp":1}', true),
('Hummus con bastones de verdura', 'Colación vegetal alta en fibra.', 'colacion', '{normal,vegetariana,dislipidemia,diabetes}', 2, 15,
 '[{"name":"Garbanzo cocido","quantity":"1","unit":"taza"},{"name":"Tahini","quantity":"1","unit":"cucharada"},{"name":"Limón","quantity":"1","unit":"pieza"},{"name":"Ajo","quantity":"1","unit":"diente"},{"name":"Zanahoria, pepino y jícama","quantity":"2","unit":"tazas"}]',
 '{"Licúa garbanzo, tahini, jugo de limón, ajo y agua hasta obtener una pasta.","Corta las verduras en bastones.","Sirve 1/2 taza de hummus por porción con las verduras."}',
 '{"leguminosas":1,"grasas_cp":0.5,"verduras":1}', true),
('Pechuga a la plancha con ensalada y arroz', 'Comida balanceada básica.', 'comida', '{normal,diabetes,hipertension,alta_proteina}', 1, 25,
 '[{"name":"Pechuga de pollo","quantity":"120","unit":"g"},{"name":"Lechuga, jitomate y pepino","quantity":"2","unit":"tazas"},{"name":"Arroz cocido","quantity":"1/2","unit":"taza"},{"name":"Aceite de oliva","quantity":"2","unit":"cucharaditas"},{"name":"Limón y hierbas","quantity":"al gusto","unit":""}]',
 '{"Marina la pechuga con limón, ajo y hierbas 10 minutos.","Ásala a la plancha 6 minutos por lado.","Prepara la ensalada y adereza con aceite y limón.","Sirve con el arroz."}',
 '{"aoa_mb":4,"verduras":2,"cereales_sg":1,"grasas_sp":2}', true),
('Salmón al horno con espárragos y camote', 'Rico en omega 3.', 'comida', '{normal,dislipidemia,embarazo,diabetes}', 1, 30,
 '[{"name":"Salmón","quantity":"90","unit":"g"},{"name":"Espárragos","quantity":"1","unit":"taza"},{"name":"Camote","quantity":"2/3","unit":"taza"},{"name":"Aceite de oliva","quantity":"1","unit":"cucharadita"}]',
 '{"Precalienta el horno a 200 °C.","Coloca el salmón, espárragos y camote en cubos en una charola.","Barniza con aceite y sazona con eneldo y limón.","Hornea 18-20 minutos."}',
 '{"aoa_b":3,"verduras":1,"cereales_sg":2,"grasas_sp":1}', true),
('Caldo de pollo con verduras', 'Bajo en sodio, ideal en recuperación.', 'comida', '{normal,hipertension,renal}', 4, 60,
 '[{"name":"Muslo de pollo sin piel","quantity":"4","unit":"piezas"},{"name":"Calabacita","quantity":"2","unit":"piezas"},{"name":"Zanahoria","quantity":"2","unit":"piezas"},{"name":"Chayote","quantity":"1","unit":"pieza"},{"name":"Arroz","quantity":"1/2","unit":"taza crudo"},{"name":"Cilantro, cebolla, ajo","quantity":"al gusto","unit":""}]',
 '{"Cuece el pollo con cebolla y ajo 30 minutos; retira la espuma.","Agrega zanahoria y chayote 10 minutos.","Añade calabacita y arroz 10 minutos más.","Sazona con hierbas y limón; evita el consomé en polvo."}',
 '{"aoa_b":2,"verduras":1.5,"cereales_sg":1}', true),
('Ensalada de lentejas mediterránea', 'Proteína vegetal y fibra.', 'comida', '{normal,vegetariana,dislipidemia,diabetes}', 2, 20,
 '[{"name":"Lenteja cocida","quantity":"1","unit":"taza"},{"name":"Jitomate cherry","quantity":"1","unit":"taza"},{"name":"Pepino","quantity":"1","unit":"pieza"},{"name":"Queso panela","quantity":"80","unit":"g"},{"name":"Aceite de oliva","quantity":"2","unit":"cucharaditas"},{"name":"Perejil y limón","quantity":"al gusto","unit":""}]',
 '{"Escurre las lentejas cocidas.","Pica jitomate, pepino y queso en cubos.","Mezcla todo con perejil, aceite y limón."}',
 '{"leguminosas":1,"verduras":1,"aoa_b":1,"grasas_sp":1}', true),
('Tacos de pescado con repollo', 'Pescado blanco bajo en grasa.', 'comida', '{normal,hipertension,dislipidemia}', 1, 20,
 '[{"name":"Filete de tilapia","quantity":"120","unit":"g"},{"name":"Tortilla de maíz","quantity":"3","unit":"piezas"},{"name":"Repollo morado rallado","quantity":"1","unit":"taza"},{"name":"Aguacate","quantity":"1/3","unit":"pieza"},{"name":"Pico de gallo","quantity":"1/2","unit":"taza"}]',
 '{"Sazona el pescado con ajo, comino y limón.","Cocínalo a la plancha 4 minutos por lado y desmenúzalo.","Calienta las tortillas y arma los tacos con repollo, aguacate y pico de gallo."}',
 '{"aoa_mb":3,"cereales_sg":3,"verduras":1,"grasas_sp":1}', true),
('Tinga de pollo baja en sodio', 'Clásico mexicano adaptado.', 'comida', '{normal,hipertension}', 4, 35,
 '[{"name":"Pechuga de pollo deshebrada","quantity":"400","unit":"g"},{"name":"Jitomate","quantity":"4","unit":"piezas"},{"name":"Cebolla fileteada","quantity":"1","unit":"pieza"},{"name":"Chipotle","quantity":"1","unit":"pieza"},{"name":"Aceite","quantity":"4","unit":"cucharaditas"},{"name":"Tostada horneada","quantity":"8","unit":"piezas"}]',
 '{"Licúa jitomate con chipotle y ajo (sin consomé).","Acitrona la cebolla en el aceite.","Agrega la salsa y el pollo; cocina 10 minutos.","Sirve sobre tostadas horneadas con lechuga."}',
 '{"aoa_mb":3,"verduras":1,"grasas_sp":1,"cereales_sg":1}', true),
('Bowl de quinoa, pollo y verduras asadas', 'Sin gluten.', 'comida', '{normal,celiaquia,alta_proteina}', 1, 30,
 '[{"name":"Quinoa cocida","quantity":"2/3","unit":"taza"},{"name":"Pechuga de pollo","quantity":"90","unit":"g"},{"name":"Pimiento, calabacita y cebolla","quantity":"1 1/2","unit":"taza"},{"name":"Aguacate","quantity":"1/3","unit":"pieza"}]',
 '{"Asa las verduras en sartén con un poco de agua.","Cocina el pollo a la plancha y córtalo en tiras.","Monta el bowl con quinoa, verduras, pollo y aguacate."}',
 '{"cereales_sg":2,"aoa_mb":3,"verduras":1.5,"grasas_sp":1}', true),
('Pescado empapelado con verduras (renal)', 'Bajo en potasio y fósforo; verduras remojadas.', 'comida', '{renal,hipertension}', 1, 30,
 '[{"name":"Filete de pescado blanco","quantity":"60","unit":"g"},{"name":"Calabacita remojada","quantity":"1/2","unit":"taza"},{"name":"Pimiento","quantity":"1/2","unit":"taza"},{"name":"Arroz blanco cocido","quantity":"1","unit":"taza"},{"name":"Aceite de canola","quantity":"2","unit":"cucharaditas"}]',
 '{"Pela y corta la verdura; remójala 2 horas cambiando el agua (técnica de lixiviación).","Coloca pescado y verduras en papel aluminio con hierbas y aceite.","Hornea 20 minutos a 190 °C.","Sirve con arroz blanco. Sin sal ni sustitutos de sal con potasio."}',
 '{"aoa_mb":1.5,"verduras":1,"cereales_sg":2,"grasas_sp":2}', true),
('Pasta integral con verduras y atún', 'Comida práctica.', 'comida', '{normal,dislipidemia}', 1, 20,
 '[{"name":"Pasta integral cocida","quantity":"1","unit":"taza"},{"name":"Atún en agua","quantity":"1","unit":"lata"},{"name":"Brócoli y jitomate","quantity":"1","unit":"taza"},{"name":"Aceite de oliva","quantity":"1","unit":"cucharadita"}]',
 '{"Cuece la pasta al dente.","Saltea las verduras con ajo y aceite.","Agrega el atún escurrido y la pasta; mezcla con albahaca."}',
 '{"cereales_sg":2,"aoa_mb":3,"verduras":1,"grasas_sp":1}', true),
('Sopa de verduras con fideo sin gluten', 'Apta para celiaquía (usar fideo de arroz).', 'comida', '{celiaquia,normal}', 2, 25,
 '[{"name":"Fideo de arroz","quantity":"60","unit":"g"},{"name":"Jitomate","quantity":"2","unit":"piezas"},{"name":"Zanahoria y calabacita","quantity":"1","unit":"taza"},{"name":"Aceite","quantity":"2","unit":"cucharaditas"}]',
 '{"Dora el fideo en el aceite.","Licúa jitomate con ajo y cebolla; agrégalo.","Añade agua y verduras; cocina 15 minutos."}',
 '{"cereales_sg":1,"verduras":1,"grasas_sp":1}', true),
('Arroz con pollo bajo FODMAP', 'Para síndrome de intestino irritable (fase de eliminación).', 'comida', '{sii,normal}', 2, 35,
 '[{"name":"Arroz","quantity":"1/2","unit":"taza crudo"},{"name":"Pechuga de pollo","quantity":"200","unit":"g"},{"name":"Zanahoria y calabacita","quantity":"1","unit":"taza"},{"name":"Aceite infusionado con ajo","quantity":"2","unit":"cucharaditas"},{"name":"Cebollín (parte verde)","quantity":"al gusto","unit":""}]',
 '{"Dora el pollo en cubos con el aceite infusionado (sin trozos de ajo ni cebolla).","Agrega el arroz y las verduras.","Cubre con agua y cocina tapado 20 minutos.","Decora con la parte verde del cebollín."}',
 '{"cereales_sg":2,"aoa_mb":3,"verduras":0.5,"grasas_sp":1}', true),
('Ensalada de nopales con queso panela', 'Cena ligera con bajo índice glucémico.', 'cena', '{normal,diabetes,hipertension}', 1, 15,
 '[{"name":"Nopales cocidos","quantity":"1","unit":"taza"},{"name":"Jitomate y cebolla","quantity":"1/2","unit":"taza"},{"name":"Queso panela","quantity":"40","unit":"g"},{"name":"Tostada horneada","quantity":"2","unit":"piezas"},{"name":"Cilantro y limón","quantity":"al gusto","unit":""}]',
 '{"Enjuaga los nopales cocidos.","Mezcla con jitomate, cebolla, cilantro y limón.","Sirve con el queso en cubos y las tostadas."}',
 '{"verduras":1.5,"aoa_b":1,"cereales_sg":1}', true),
('Sándwich integral de pavo y aguacate', 'Cena rápida.', 'cena', '{normal}', 1, 5,
