update recipes r set
  kcal = round(x.kcal), protein_g = round(x.p, 1), fat_g = round(x.f, 1), carbs_g = round(x.c, 1)
from (
  select r2.id,
    sum(e.value::numeric * g.kcal) kcal, sum(e.value::numeric * g.protein_g) p,
    sum(e.value::numeric * g.fat_g) f, sum(e.value::numeric * g.carbs_g) c
  from recipes r2, jsonb_each_text(r2.equivalents) e
  join equivalent_groups g on g.code = e.key
  group by r2.id
) x where x.id = r.id;

