-- ============ Material educativo ============
insert into education_materials (title, category, description, body) values
('El plato del bien comer', 'Alimentación saludable', 'Guía básica para armar tus comidas.',
 'Incluye en cada comida los tres grupos: verduras y frutas (la mitad del plato), cereales preferentemente integrales y leguminosas o alimentos de origen animal. Combina cereales con leguminosas, toma agua simple y modera azúcares, sal y grasas.'),
('Cómo usar tu lista de equivalentes', 'Plan de alimentación', 'Aprende a intercambiar alimentos.',
 'Cada equivalente de un mismo grupo aporta casi la misma energía y nutrimentos. Si tu plan indica 2 equivalentes de cereales en la comida, puedes elegir 2 tortillas, 1 taza de arroz o 1 tortilla + 1/2 taza de arroz. Respeta las cantidades y los grupos indicados.'),
('Lectura de etiquetas y sellos', 'Alimentación saludable', 'Interpreta el etiquetado frontal.',
 'Prefiere productos con menos sellos. Revisa la porción, los azúcares añadidos, el sodio y la grasa saturada en la tabla nutrimental. La lista de ingredientes va de mayor a menor cantidad.'),
('Hidratación', 'Hábitos', 'Cuánta agua necesitas.',
 'Una referencia general es 30-35 ml por kg de peso al día, más lo perdido con el ejercicio. Tu orina debe ser de color amarillo claro. Evita bebidas azucaradas.'),
('Higiene y desinfección de alimentos', 'Seguridad alimentaria', 'Prevén enfermedades.',
 'Lava tus manos antes de cocinar, desinfecta frutas y verduras, separa alimentos crudos de cocidos y refrigera las sobras antes de 2 horas.');

